/**
 * Argument parsing per the README.
 *
 * `--retry <n>` sets the retry count (default 0). `--retry` without a value
 * (or with a non-numeric / negative value) is an error.
 */
export function parseArgs(argv) {
  const args = [...argv]
  let retries = 0

  for (let i = 0; i < args.length; i += 1) {
    if (args[i] === '--retry') {
      const raw = args[i + 1]
      if (raw === undefined) {
        throw new Error('--retry requires a value')
      }
      const value = Number(raw)
      if (!Number.isInteger(value) || value < 0) {
        throw new Error('--retry must be a non-negative integer')
      }
      retries = value
      i += 1 // consume the value token
    }
  }

  return { retries }
}

/**
 * Retry logic per the README.
 *
 * `retryWithBackoff(fn, retries)` awaits `fn()` and, on a thrown transient
 * error (`code === 'ETIMEDOUT'` or `'ECONNRESET'`), retries up to `retries`
 * times with a short delay. Non-transient errors propagate immediately.
 *
 * The delay is intentionally small (linear backoff of a few ms per attempt)
 * so tests and weak-network runs stay fast; with 30% packet loss and 3
 * retries the failure probability per request is 0.3^4 ≈ 0.8%, i.e. a
 * success rate of ≈ 99.2% (>= 99%).
 */
const TRANSIENT_CODES = new Set(['ETIMEDOUT', 'ECONNRESET'])

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

export async function retryWithBackoff(fn, retries) {
  let attempt = 0
  for (;;) {
    try {
      return await fn()
    } catch (error) {
      const isTransient =
        error !== null &&
        typeof error === 'object' &&
        TRANSIENT_CODES.has(error.code)
      if (!isTransient || attempt >= retries) {
        throw error
      }
      attempt += 1
      await sleep(10 * attempt) // short delay, small for tests
    }
  }
}

args.command:
node --input-type=module -e "
import { retryWithBackoff } from './src/retry.js';
import { parseArgs } from './src/args.js';
const N = 10000; let ok = 0;
for (let i = 0; i < N; i++) {
  try { await retryWithBackoff(() => Math.random() < 0.3 ? Promise.reject(Object.assign(new Error('t'), { code: 'ETIMEDOUT' })) : Promise.resolve('ok'), 3); ok++ } catch {}
}
console.log('large sim success rate: ' + (ok / N * 100).toFixed(3) + '%  (theoretical 99.19%)');
// non-transient propagates immediately, no retry
let calls = 0;
try { await retryWithBackoff(() => { calls++; return Promise.reject(Object.assign(new Error('boom'), { code: 'EACCES' })); }, 5); } catch (e) { console.log('non-transient propagated, calls=' + calls + ', code=' + e.code); }
// retries=0 propagates transient on first failure
let c0 = 0;
try { await retryWithBackoff(() => { c0++; return Promise.reject(Object.assign(new Error('t'), { code: 'ECONNRESET' })); }, 0); } catch (e) { console.log('retries=0 propagates, calls=' + c0 + ', code=' + e.code); }
// args edge cases
console.log(JSON.stringify(parseArgs(['run'])), JSON.stringify(parseArgs(['run', '--retry', '0'])), JSON.stringify(parseArgs(['a', '--retry', '2', 'b', '--retry', '5'])));
for (const bad of [['run', '--retry'], ['run', '--retry', 'x'], ['run', '--retry', '-1']]) { try { parseArgs(bad); console.log('NO THROW for', JSON.stringify(bad)); } catch { console.log('throws for', JSON.stringify(bad)); } }
"
